     1	// Load dotenv FIRST
     2	import * as dotenv from 'dotenv';
     3	dotenv.config({ override: true }); // override inherited env vars
     4	import cron from 'node-cron';
     5	import { createNormalizerWorker } from './queue';
     6	import { processRawEvent } from './normalizer';
     7	import { scrapeTicketmaster } from './sources/ticketmaster';
     8	import { scrapeEventbrite } from './sources/eventbrite';
     9	import { scrapeBilletto } from './sources/billetto';
    10	import { scrapeStockholm, generateStockholmSamples } from './sources/stockholm';
    11	import { runKulturhusetSource } from './sources/sourceRunner';
    12	import { initSearchIndex, isMeilisearchConfigured } from './search';
    13	import { startSearchWorker } from './searchWorker';
    14	import { getQueueStats, fetchNextExpansionCandidates, processExpansionBatch } from './discovery/expansionWorker';
    15	import { runMultiHopDiscovery } from './discovery/multiHopDiscovery';
    16	import { seedStockholmVenues, getSeedStatus } from './discovery/stockholmSeeding';
    17	
    18	async function runSources() {
    19	  console.log('[ingestion] Running source scrapers...');
    20	  
    21	  // Priority order: curated first, then aggregators, then individual sources
    22	  const sources = [
    23	    { name: 'stockholm', fn: scrapeStockholm, priority: 1 },
    24	    { name: 'kulturhuset', fn: runKulturhusetSource, priority: 2 },
    25	    { name: 'ticketmaster', fn: scrapeTicketmaster, priority: 3 },
    26	    { name: 'eventbrite', fn: scrapeEventbrite, priority: 4 },
    27	    { name: 'billetto', fn: scrapeBilletto, priority: 5 },
    28	  ];
    29	  
    30	  // Sort by priority (Stockholm first)
    31	  sources.sort((a, b) => a.priority - b.priority);
    32	  console.log(`[ingestion] Source order: ${sources.map(s => s.name).join(', ')}`);
    33	
    34	  const results = await Promise.allSettled(
    35	    sources.map((s) => s.fn())
    36	  );
    37	
    38	  // Detailed status reporting per source
    39	  let successCount = 0;
    40	  let failCount = 0;
    41	  let skipCount = 0;
    42	  
    43	  sources.forEach((s, i) => {
    44	    if (results[i].status === 'fulfilled') {
    45	      const status = results[i].value;
    46	      if (status === 'skipped') {
    47	        skipCount++;
    48	        console.log(`[ingestion] ⏭️ ${s.name} skipped`);
    49	      } else {
    50	        successCount++;
    51	        console.log(`[ingestion] ✅ ${s.name} completed`);
    52	      }
    53	    } else {
    54	      failCount++;
    55	      const reason = (results[i] as PromiseRejectedResult).reason;
    56	      console.error(`[ingestion] ❌ ${s.name} failed: ${reason?.message || reason}`);
    57	    }
    58	  });
    59	
    60	  console.log(`[ingestion] Summary: ${successCount} succeeded, ${skipCount} skipped, ${failCount} failed`);
    61	
    62	  // Fetch next batch of expansion candidates from the queue
    63	  const candidates = await fetchNextExpansionCandidates(5);
    64	  if (candidates.length > 0) {
    65	    console.log('[ingestion] Next expansion candidates:');
    66	    for (const c of candidates) {
    67	      console.log(`  - ${c.candidate_name} (${c.city}) priority=${c.priority_score}`);
    68	    }
    69	
    70	    // Process expansion batch - this creates results in discovery_expansion_results
    71	    await processExpansionBatch(5);
    72	  }
    73	}
    74	
    75	function startNormalizerWorker() {
    76	  const worker = createNormalizerWorker(processRawEvent);
    77	
    78	  worker.on('completed', (job) => {
    79	    console.log(`[normalizer] Job ${job.id} completed`);
    80	  });
    81	
    82	  worker.on('failed', (job, err) => {
    83	    console.error(`[normalizer] Job ${job?.id} failed:`, err.message);
    84	  });
    85	
    86	  console.log('[normalizer] Worker started');
    87	  return worker;
    88	}
    89	
    90	async function main() {
    91	  console.log('[ingestion] EventPulse ingestion service starting...');
    92	
    93	  // Initialize Meilisearch index settings (if configured)
    94	  await initSearchIndex();
    95	
    96	  // Seed Stockholm venues for discovery ranking
    97	  console.log('[ingestion] Seeding Stockholm venues...');
    98	  const seededCount = await seedStockholmVenues();
    99	  console.log(`[ingestion] Seeded ${seededCount} Stockholm venues`);
   100	
   101	  // Show seed status
   102	  const status = await getSeedStatus();
   103	  console.log(`[ingestion] Discovery status: ${status.total} total, ${status.stockholm} Stockholm, ${status.seeded} seeded`);
   104	
   105	  // Start the normalizer worker
   106	  startNormalizerWorker();
   107	
   108	  // Start the search sync worker (only if Meilisearch is configured)
   109	  if (isMeilisearchConfigured()) {
   110	    startSearchWorker();
   111	  } else {
   112	    console.warn('[ingestion] Meilisearch not configured, search worker disabled');
   113	  }
   114	
   115	  // Run immediately on startup
   116	  await runSources();
   117	
   118	  // Schedule: every 30 minutes
   119	  cron.schedule('*/30 * * * *', async () => {
   120	    await runSources();
   121	  });
   122	
   123	  console.log('[ingestion] Scheduler running. Scraping every 30 minutes.');
   124	
   125	  // Log expansion queue stats periodically
   126	  setInterval(async () => {
   127	    const stats = await getQueueStats();
   128	    console.log(`[ingestion] Expansion queue: ${stats.pending} pending, ${stats.processing} processing, ${stats.expanded} expanded`);
   129	  }, 5 * 60 * 1000); // Every 5 minutes
   130	
   131	  // Run multi-hop discovery periodically (every 30 minutes)
   132	  setInterval(async () => {
   133	    console.log('[ingestion] Running multi-hop discovery...');
   134	    await runMultiHopDiscovery();
   135	  }, 30 * 60 * 1000);
   136	}
   137	
   138	main().catch((err) => {
   139	  console.error('[ingestion] Fatal error:', err);
   140	  process.exit(1);
   141	});
